<template><view class="account-page feature-page"><view class="business-filters"><picker v-if="resource?.type==='dividends'||resource?.id==='global-awards'" mode="date" fields="month" :value="month" @change="changeMonth"><view class="business-small-button">{{month}} <image class="month-chevron" src="/static/common/icon-chevron-right.png" mode="aspectFit"/></view></picker><input v-if="resource?.type==='team'||resource?.type==='income'" v-model="keyword" placeholder="输入关键词搜索" confirm-type="search" @confirm="load"/><button v-if="resource?.type==='team'||resource?.type==='income'" @click="load">搜索</button><button v-if="resource?.type==='income'" :class="{selected:filter==='pending'}" @click="togglePending">{{filter==='pending'?'显示全部':'筛选待分配提成'}}</button><button @click="load">刷新</button></view><view v-if="context?.module==='wholesale'&&relatedTools.length" class="business-filters"><button v-for="item in relatedTools" :key="item.id" @click="memberOperation(item.id,'')">{{item.label}}</button></view><FeaturePageState :status="status" :error="error" @retry="load"/><template v-if="status==='ready'"><text class="feature-note">{{context.label}}</text><view v-if="report.metrics?.length" class="business-metrics"><view v-for="metric in report.metrics" :key="metric.label" class="business-metric"><text>{{metric.label}}</text><view>{{formatValue(metric.value,metric.kind)}}</view></view></view><view v-if="resource.type==='income'" class="business-filters"><button v-if="canWallet('read')" @click="withdrawals">提现记录</button><button v-if="canWallet('withdraw')" @click="withdraw">申请提现</button></view><button v-if="resource.type==='relations'" class="primary" @click="bindSuperior">绑定上级</button><template v-if="resource.type==='share'"><image v-if="report.qrUrl" class="business-share-image" :src="report.qrUrl" mode="aspectFit"/><BusinessQrCode v-else-if="isMock&&report.localPayload" :value="report.localPayload"/><EmptyState v-else text="暂无分享码"/><button v-if="report.shareUrl" class="primary" @click="copyShare">复制分享链接</button></template><template v-else-if="report.columns?.length"><scroll-view scroll-x class="business-table-scroll"><view class="business-table"><view class="business-table-row business-table-head"><text v-for="column in report.columns" :key="column.key" class="business-table-cell">{{column.label}}</text></view><view v-for="row in items" :key="row.id" class="business-table-row"><text v-for="column in report.columns" :key="column.key" class="business-table-cell">{{formatValue(row[column.key],column.kind)}}</text></view></view></scroll-view></template><template v-else><view v-for="item in items" :key="item.id" class="business-record"><view class="business-row"><text class="business-record-title">{{item.title||item.name}}</text><text v-if="Number.isInteger(item.amount)" class="business-amount">{{item.amount>0?'+':''}}{{money(item.amount)}}</text><text v-if="item.levelLabel" class="business-tag">{{item.levelLabel}}</text></view><text v-if="item.description||item.scopeLabel" class="business-caption">{{item.description||item.scopeLabel}}</text><text v-if="item.progressLabel" class="business-caption">{{item.progressLabel}}</text><text v-if="item.sourceLabel" class="business-caption">{{item.sourceLabel}}</text><text v-if="item.targetName" class="business-caption">对象：{{item.targetName}}</text><text v-if="item.storeId" class="business-caption">绑定门店：{{item.storeId}}</text><view v-if="item.quantity != null" class="business-row"><text>数量变动</text><text>{{item.quantity>0?'+':''}}{{item.quantity}}</text></view><view v-if="item.remaining != null" class="business-row"><text>剩余名额</text><text>{{item.remaining}}</text></view><text v-if="item.createdAt" class="business-caption">{{dateLabel(item.createdAt)}}</text><template v-if="resource.type==='team'&&context.module==='agency'"><view class="business-row"><text>业绩统计</text><text>{{item.storeCount ?? '—'}}家门店，{{item.ownerCount ?? '—'}}位合店老板</text></view><view v-if="item.performance?.length" class="business-metrics"><view v-for="metric in item.performance" :key="metric.label" class="business-metric"><text>{{metric.label}}</text><view>{{formatValue(metric.value,metric.kind)}}</view></view></view><button class="primary" @click="teamDetail(item.id)">查看详情</button></template><view v-if="resource.type==='team'&&context.module==='wholesale'" class="business-filters"><button @click="memberOperation('upgrade',item.id)">开通/升级</button><button @click="memberOperation('bind-store',item.id)">绑定门店</button></view><template v-if="resource.type==='income'"><view class="business-row"><text>{{item.channel}}</text><button class="business-link" @click="incomeDetail(item.id)">查看详情</button></view><text v-if="item.allocationStatus==='PENDING'" class="feature-note">本单存在待分配提点，暂不计入可提现金额</text><text v-else-if="item.settlementStatus==='PENDING_SETTLEMENT'" class="feature-note">提点已分配，等待后台结算</text></template><button v-if="resource.type==='tasks'" class="business-link" @click="memberOperation('upgrade','')">前往开通/升级</button></view></template><EmptyState v-if="!items.length&&resource.type!=='share'" text="暂无记录"/><button v-if="hasMore" class="secondary" :disabled="loadingMore" @click="more">{{loadingMore?'加载中…':'加载更多'}}</button><text v-if="moreError" class="business-operation-error">{{moreError}}</text></template></view></template>
<script setup>
import {ref,watch,computed,onUnmounted} from 'vue'
import {config} from '../config'
import {findBusinessTool,businessPreview,businessTools} from '../features/business/catalog'
import {money,percent} from '../features/exclusive/format'
import {businessDateLabel} from '../features/business/format'
import {getBusinessContext,getBusinessReport,bindBusinessSuperior} from '../services/business'
import {useAsyncPage} from '../composables/useAsyncPage'
import BusinessQrCode from './BusinessQrCode.vue'
import FeaturePageState from './FeaturePageState.vue'
import EmptyState from './EmptyState.vue'
const props=defineProps({module:String,toolId:String,pageQuery:Object}),resource=computed(()=>findBusinessTool(props.module,props.toolId)),context=ref(null),now=new Date(),month=ref(`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`),keyword=ref(''),filter=ref(''),items=ref([]),loadingMore=ref(false),hasMore=ref(false),moreError=ref(''),isMock=config.useMock
const relatedTools=computed(()=>businessTools.filter(item=>item.module==='wholesale'&&({'quota-ledger':['quota-purchase','quota-batches','quota-transfer'],'quota-transfers':['quota-transfer'],promotion:['entitlement']}[props.toolId]||[]).includes(item.id)&&(businessPreview(config)||context.value?.capabilities?.includes(item.capability))))
let cursor=null,epoch=0,searchTerm=''
const {data:report,status,error,load}=useAsyncPage(async()=>{const ctx=await getBusinessContext(props.module,props.pageQuery?.contextId);context.value=ctx;searchTerm=keyword.value.trim();return getBusinessReport(props.module,props.toolId,ctx.id,{month:month.value,filter:filter.value,keyword:searchTerm,parentNodeId:props.pageQuery?.parentNodeId||null})},false)
watch(()=>props.pageQuery,query=>{if(query)load()},{immediate:true})
watch(status,value=>{if(value==='loading'){++epoch;loadingMore.value=false;moreError.value=''}})
watch(report,result=>{if(result){items.value=result.items;hasMore.value=result.hasMore;cursor=result.nextCursor}})
const formatValue=(value,kind)=>kind==='money'?`¥${money(value)}`:kind==='percent'?percent(value):value??'—'
const dateLabel=businessDateLabel
function changeMonth(event){month.value=event.detail.value;load()}
function togglePending(){filter.value=filter.value==='pending'?'':'pending';load()}
function canWallet(action){return businessPreview(config)||context.value?.capabilities.includes(`wallet:${action}`)}
function withdraw(){uni.navigateTo({url:`/pages/wallet/withdraw-apply?contextId=${encodeURIComponent(context.value.id)}`})}
function withdrawals(){uni.navigateTo({url:`/pages/wallet/withdrawals?contextId=${encodeURIComponent(context.value.id)}`})}
function incomeDetail(id){uni.navigateTo({url:`/pages/income/detail?contextId=${encodeURIComponent(context.value.id)}&id=${encodeURIComponent(id)}`})}
function teamDetail(id){uni.navigateTo({url:`/pages/agency/team-detail?contextId=${encodeURIComponent(context.value.id)}&nodeId=${encodeURIComponent(id)}`})}
function memberOperation(kind,id){uni.navigateTo({url:`/pages/partner/${kind}?contextId=${encodeURIComponent(context.value.id)}${id?`&targetAccountId=${encodeURIComponent(id)}`:''}`})}
function bindSuperior(){uni.showModal({title:'绑定上级',editable:true,placeholderText:'请输入上级手机号',success:async result=>{if(!result.confirm)return;try{await bindBusinessSuperior(context.value.id,result.content);await load()}catch(e){moreError.value=e.message;uni.showToast({title:e.message,icon:'none'})}}})}
async function copyShare(){try{const result=await getBusinessReport(props.module,props.toolId,context.value.id);if(!result.shareUrl)throw new Error('分享链接已失效');uni.setClipboardData({data:result.shareUrl})}catch(reason){moreError.value=reason.message}}
async function more(){if(loadingMore.value||!hasMore.value)return;const current=epoch;loadingMore.value=true;try{const result=await getBusinessReport(props.module,props.toolId,context.value.id,{month:month.value,filter:filter.value,keyword:searchTerm,cursor,parentNodeId:props.pageQuery?.parentNodeId||null});if(current===epoch){items.value=[...new Map([...items.value,...result.items].map(item=>[item.id,item])).values()];cursor=result.nextCursor;hasMore.value=result.hasMore}}catch(reason){if(current===epoch)moreError.value=reason.message}finally{if(current===epoch)loadingMore.value=false}}
onUnmounted(()=>{++epoch});defineExpose({refresh:load})
</script>
<style>@import '../styles/account.css';@import '../styles/exclusive.css';@import '../styles/business.css';</style>
<style scoped>.month-chevron{height:1em;width:1em;vertical-align:middle;margin-left:.5em}.business-share-image{display:block;width:60%;max-width:20em;aspect-ratio:1;margin:2em auto}</style>
